mapper.select:
select id, user_id, title, type, responder_id, handled, create_time, update_time, remark
from im_chat_session
where id = #{id}

select id, user_id, title, type, responder_id, handled, create_time, update_time, remark
from im_chat_session

    and user_id = #{userId}
    and type = #{type}
    and responder_id = #{responderId}
    and title like concat('%', #{title}, '%')

order by create_time desc, id desc

mapper.update:
update im_chat_session
set handled = #{handled}, update_time = NOW()
where id = #{id}
